(function(){
  var P = AutoJS.players()[0];
  var L = AutoJS.level();
  var CSU = Java.loadClass('com.merlinkitsune.astral_dice.item.CurioSlotUtil');
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  var NLI = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.NancyLuSignItem');
  var gmm = new RegExp('"gameMode":"([a-z_]+)"').exec(String(AutoJS.state()));
  var gmName = gmm === null ? 'creative' : gmm[1];
  AutoJS.write('astral_test_state.txt', gmName + '|' + P.getX() + '|' + P.getY() + '|' + P.getZ());
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  AutoJS.command('gamemode survival @a');
  var out = {};
  out.diceEquipped = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:diamond_dice', 1), 'dice').getResult().consumesAction();
  out.signEquipped = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:nancy_lu_sign', 1), 'stand').getResult().consumesAction();
  out.nancyEquipped = NLI.isEquipped(P);
  out.immuneTicksConst = NLI.ENDER_PEARL_IMMUNE_TICKS;
  MA.setNancyLuEnderPearlImmuneUntil(P, 0);
  out.windowBefore = MA.getNancyLuEnderPearlImmuneUntil(P);
  P.setHealth(12.0);
  out.healthBefore = P.getHealth();
  P.getInventory().selected = 0;
  P.getInventory().setItem(0, AutoJS.stack('minecraft:ender_pearl', 1));
  var held = AutoJS.held(P);
  out.heldId = held.isEmpty() ? 'empty' : String(AutoJS.id(held));
  out.gameTimeBefore = L.getGameTime();
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var used = AutoJS.use();
  var held = AutoJS.held(P);
  return { threwPearl: used, heldAfterThrow: held.isEmpty() ? 'empty' : String(AutoJS.id(held)) };
})()

(function(){
  var P = AutoJS.players()[0];
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  return MA.getNancyLuEnderPearlImmuneUntil(P) > 0;
})()

(function(){
  var P = AutoJS.players()[0];
  var L = AutoJS.level();
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  var out = {};
  out.windowObserved = MA.getNancyLuEnderPearlImmuneUntil(P);
  out.windowWasSet = out.windowObserved > 0;
  out.healthAfterPearl = P.getHealth();
  out.pearlFallDamageCanceled = Math.abs(P.getHealth() - 12.0) < 0.001;
  P.setHealth(12.0);
  MA.setNancyLuEnderPearlImmuneUntil(P, L.getGameTime() + 400);
  var hpImmune = P.getHealth();
  out.hurtWhileImmune = P.hurt(L.damageSources().fall(), 3.0);
  out.deltaWhileImmune = hpImmune - P.getHealth();
  MA.setNancyLuEnderPearlImmuneUntil(P, 0);
  var hpOpen = P.getHealth();
  out.hurtAfterWindow = P.hurt(L.damageSources().fall(), 3.0);
  out.deltaAfterWindow = hpOpen - P.getHealth();
  out.windowFinal = MA.getNancyLuEnderPearlImmuneUntil(P);
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
  var MA = Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var stp = String(AutoJS.read('astral_test_state.txt')).split('|');
  var gm = stp[0], x = Number(stp[1]), y = Number(stp[2]), z = Number(stp[3]);
  MA.setNancyLuEnderPearlImmuneUntil(P, 0);
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  var inv = Cur.getCuriosInventory(P).get();
  inv.getStacksHandler('stand').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  inv.getStacksHandler('dice').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  P.moveTo(x, y, z);
  P.setDeltaMovement(0.0, 0.0, 0.0);
  P.resetFallDistance();
  P.setHealth(P.getMaxHealth());
  AutoJS.command('gamemode ' + gm + ' @a');
  var out = {};
  out.windowFinal = MA.getNancyLuEnderPearlImmuneUntil(P);
  out.diceSlotEmptyAfter = inv.getStacksHandler('dice').get().getStacks().getStackInSlot(0).isEmpty();
  out.standSlotEmptyAfter = inv.getStacksHandler('stand').get().getStacks().getStackInSlot(0).isEmpty();
  out.chipSlotsFinal = inv.getStacksHandler('chip').get().getSlots();
  out.gameModeRestored = String(AutoJS.state()).indexOf('"gameMode":"' + gm + '"') >= 0;
  out.healthRestored = (P.getHealth() >= P.getMaxHealth() - 0.001);
  return out;
})()
